/** Looks up a brand icon by its stored name (`brand:facebook`). */
export function brandIconFor(name: string | undefined): BrandIcon | undefined {
  if (!name || !name.startsWith(BRAND_ICON_PREFIX)) return undefined;
  return BRAND_ICONS[name.slice(BRAND_ICON_PREFIX.length).toLowerCase()];
}
